effect.shader:
vec4 getFromColor(vec2 coord){ return texture2DCv(inputImg.texture, coord); }
vec4 getToColor(vec2 coord){ return texture2DCv(inputImg2.texture, coord); }
vec4 getMask(vec2 coord){ return texture2DCv(mask.texture, coord); }
void main(){
  vec2 uv = acLayerNorm;
  float s = getMask(uv).a;
  vec4 fromCol = getFromColor(uv);
  vec4 toCol = getToColor(uv);
  float rev = step(0.5, reverse);
  vec4 f = mix(fromCol, toCol, rev);
  vec4 t = mix(toCol, fromCol, rev);
  vec4 col = mix(f, t, s);
  gl_FragColor = col;
}
